int32 ForceJumpPeakSubstep = 1;
FAutoConsoleVariableRef CVarForceJumpPeakSubstep(
	TEXT("p.ForceJumpPeakSubstep"),
	ForceJumpPeakSubstep,
	TEXT("If 1, force a jump substep to always reach the peak position of a jump, which can often be cut off as framerate lowers."),
	ECVF_Default);

// If jump is providing force, gravity may be affected.
bool bEndingJumpForce = false;
if (CharacterOwner->JumpForceTimeRemaining > 0.0f)
{
	// Consume some of the force time. Only the remaining time (if any) is affected by gravity when bApplyGravityWhileJumping=false.
	const float JumpForceTime = FMath::Min(CharacterOwner->JumpForceTimeRemaining, timeTick);
	GravityTime = bApplyGravityWhileJumping ? timeTick : FMath::Max(0.0f, timeTick - JumpForceTime);

	// Update Character state
	CharacterOwner->JumpForceTimeRemaining -= JumpForceTime;
	if (CharacterOwner->JumpForceTimeRemaining <= 0.0f)
	{
		CharacterOwner->ResetJumpState();
		bEndingJumpForce = true;
	}
}

// Apply gravity
Velocity = NewFallVelocity(Velocity, Gravity, GravityTime);

//UE_LOGF(LogCharacterMovement, Log, "dt=(%.6f) OldLocation=(%ls) OldVelocity=(%ls) OldVelocityWithRootMotion=(%ls) NewVelocity=(%ls)", timeTick, *(UpdatedComponent->GetComponentLocation()).ToString(), *OldVelocity.ToString(), *OldVelocityWithRootMotion.ToString(), *Velocity.ToString());
ApplyRootMotionToVelocity(timeTick);
DecayFormerBaseVelocity(timeTick);

// See if we need to sub-step to exactly reach the apex. This is important for avoiding "cutting off the top" of the trajectory as framerate varies.
const FVector::FReal GravityRelativeOldVelocityWithRootMotionZ = GetGravitySpaceZ(OldVelocityWithRootMotion);
if (CharacterMovementCVars::ForceJumpPeakSubstep && GravityRelativeOldVelocityWithRootMotionZ > 0.f && GetGravitySpaceZ(Velocity) <= 0.f && NumJumpApexAttempts < MaxJumpApexAttemptsPerSimulation)
{
	const FVector DerivedAccel = (Velocity - OldVelocityWithRootMotion) / timeTick;
	const FVector::FReal GravityRelativeDerivedAccelZ = GetGravitySpaceZ(DerivedAccel);
	if (!FMath::IsNearlyZero(GravityRelativeDerivedAccelZ))
	{
		const float TimeToApex = -GravityRelativeOldVelocityWithRootMotionZ / GravityRelativeDerivedAccelZ;

		// The time-to-apex calculation should be precise, and we want to avoid adding a substep when we are basically already at the apex from the previous iteration's work.
		const float ApexTimeMinimum = 0.0001f;
		if (TimeToApex >= ApexTimeMinimum && TimeToApex < timeTick)
		{
			const FVector ApexVelocity = OldVelocityWithRootMotion + (DerivedAccel * TimeToApex);
			if (HasCustomGravity())
			{
				Velocity = ProjectToGravityFloor(ApexVelocity); // Should be nearly zero anyway, but this makes apex notifications consistent.
			}
			else
			{
				Velocity = ApexVelocity;
				Velocity.Z = 0.f; // Should be nearly zero anyway, but this makes apex notifications consistent.
			}

			// We only want to move the amount of time it takes to reach the apex, and refund the unused time for next iteration.
			const float TimeToRefund = (timeTick - TimeToApex);

			remainingTime += TimeToRefund;
			timeTick = TimeToApex;
			Iterations--;
			NumJumpApexAttempts++;

			// Refund time to any active Root Motion Sources as well
			for (TSharedPtr<FRootMotionSource> RootMotionSource : CurrentRootMotion.RootMotionSources)
			{
				const float RewoundRMSTime = FMath::Max(0.0f, RootMotionSource->GetTime() - TimeToRefund);
				RootMotionSource->SetTime(RewoundRMSTime);
			}
		}
	}
}

if (bNotifyApex && (GetGravitySpaceZ(Velocity) < 0.f))
{
	// Just passed jump apex since now going down
	bNotifyApex = false;
	NotifyJumpApex();
}

// Compute change in position (using midpoint integration method).
FVector Adjusted = 0.5f * (OldVelocityWithRootMotion + Velocity) * timeTick;

// Move
FHitResult Hit(1.f);
SafeMoveUpdatedComponent( Adjusted, PawnRotation, true, Hit);

if (!HasValidData())
{

static void PullBackHit(FHitResult& Hit, const FVector& Start, const FVector& End, const float Dist)
{
	const float DesiredTimeBack = FMath::Clamp(0.1f, 0.1f/Dist, 1.f/Dist) + 0.001f;
	Hit.Time = FMath::Clamp( Hit.Time - DesiredTimeBack, 0.f, 1.f );
}

let mut acceleration = air_acceleration_for_horizontal_speed(params, velocity.with_y(0.0).length())
    .min(params.acceleration.max_acceleration);
let mut contact = false;
let mut mode = LocomotionState::Air;
while remaining >= crate::als::movement_constants::MIN_MOVEMENT_DELTA_SECONDS
    && iterations < params.cmc.max_simulation_iterations {
    iterations += 1;
    let step = crate::als::dynamics::source_movement_time_step(remaining, &params.cmc, iterations);
    let old_velocity = velocity;
    let horizontal = crate::als::dynamics::grounded_velocity_step_with_braking_friction(
        velocity.with_y(0.0), desired_motion, max_speed,
        crate::als::params::GroundedDynamics { acceleration, braking_deceleration: 0.0, ground_friction: 0.0 },
        params.cmc.min_analog_walk_speed, 0.0, params.cmc.braking_substep_time, step);
    velocity = crate::als::dynamics::clamp_falling_velocity(horizontal + Vec3::Y * velocity.y + gravity * step,
        gravity, terminal);
    let requested = (old_velocity + velocity) * (0.5 * step);
    let (applied, deflected, hit, landing_remaining) = falling_movement_sweep(spatial, capsule, transform.translation,
        transform.rotation, requested, velocity, step, Some(&params.cmc), entity, candidates);
    transform.translation += applied;
    contact |= hit;
    let extent = capsule.shape_scaled().compute_local_aabb().half_extents();
    if let Some(landing_remaining) = landing_remaining {
        remaining = remaining - step + landing_remaining;
        transitions.write(StateTransitionEvent { entity, dimension: Dimension::LocomotionState,
            from: StateValue::LocomotionState(LocomotionState::Air), to: StateValue::LocomotionState(LocomotionState::Grounded) });

runtime.grounded_move_start = None;
if *loco == LocomotionState::Air
    && let Ok((RigidBody::Dynamic, volume, false)) = physics_modes.get(entity)
    && !root_motion_active {
    let mut initial_transform = *transform;
    initial_transform.translation = position.0;
    let initial = velocity.0 + motor.lin.boost;
    let initial_horizontal = initial.with_y(0.0);
    let max_speed = crate::als::dynamics::max_allowed_speed(params, *stance, *rotation_mode,
        max_allowed_gait.0, initial_horizontal, view_yaw.0);
    let (moved, final_velocity, steps, contact, mode) = falling_movement_transaction(&spatial_query, capsule,
        initial_transform, initial, controller.basis.desired_motion, max_speed, params,
        gravity.value + motor.lin.acceleration, grounded, landing, volume.unwrap_or(&default_volume.0).terminal_velocity,
        delta_seconds, 0, entity, &candidates, &step_permissions, &mut transitions);
    if *loco != mode { *loco = mode; }
    if mode == LocomotionState::None {
        commands.entity(entity).insert((crate::als::state::AlsNotifyLocomotionAction::Ragdolling,
            crate::als::dynamics::AlsMovementBase::default(), LinearVelocity::ZERO));
        if let Some(base) = base.as_deref_mut() { *base = default(); }
    }
    runtime.simulation_delta_seconds = delta_seconds;
    runtime.simulation_substeps = steps;
    runtime.grounded_movement_delta = None;
    runtime.grounded_collision_velocity = Some(if mode == LocomotionState::None { Vec3::ZERO } else { final_velocity });
    runtime.airborne_sweep_contact |= contact;
    let world_position = moved.translation;
    *transform = moved;
    transform.translation = parent_world.map_or(world_position, |parent| parent.affine().inverse().transform_point3(world_position));
